mapper.insert:
INSERT INTO dataset_image(image_id, dataset_id, original_filename, storage_path, media_type, size_bytes,
  created_at, updated_at, created_by, updated_by, thumbnail_path, is_deleted, version_count, previous_image_id, description)
SELECT #{id}, #{draft.workingDatasetId}, #{entry.originalFilename}, storage_path, #{entry.mediaType}, #{entry.sizeBytes},
  #{entry.sourceCreatedAt}, #{draft.updatedAt}, #{entry.sourceCreatedBy}, #{draft.updatedBy}, thumbnail_path, FALSE,
  #{entry.versionCount}, previous_image_id, #{entry.description,jdbcType=VARCHAR}
FROM dataset_image WHERE image_id=#{entry.entryId}

INSERT INTO dataset_file(file_id, dataset_id, original_filename, storage_path, media_type, size_bytes,
  created_at, updated_at, created_by, updated_by, is_deleted, version_count, previous_file_id, description)
SELECT #{id}, #{draft.workingDatasetId}, #{entry.originalFilename}, storage_path, #{entry.mediaType}, #{entry.sizeBytes},
  #{entry.sourceCreatedAt}, #{draft.updatedAt}, #{entry.sourceCreatedBy}, #{draft.updatedBy}, FALSE,
  #{entry.versionCount}, previous_file_id, #{entry.description,jdbcType=VARCHAR}
FROM dataset_file WHERE file_id=#{entry.entryId}

mapper.select:
SELECT 'images' AS kind, image_id AS entry_id, original_filename, description, media_type, size_bytes, version_count, source_created_at, source_created_by
FROM dataset_version_image WHERE version_id=#{versionId}
UNION ALL
SELECT 'files' AS kind, file_id AS entry_id, original_filename, description, media_type, size_bytes, version_count, source_created_at, source_created_by
FROM dataset_version_file WHERE version_id=#{versionId}
ORDER BY kind, original_filename, entry_id

SELECT snap.original_filename, source.storage_path, CAST(NULL AS VARCHAR(100)) AS thumbnail_path
FROM dataset_version_file snap JOIN dataset_file source ON source.file_id=snap.file_id
WHERE snap.version_id=#{versionId} AND snap.file_id=#{entryId}

mapper.update:
UPDATE dataset_image SET is_deleted=FALSE, original_filename=#{entry.originalFilename}, description=#{entry.description,jdbcType=VARCHAR},
  media_type=#{entry.mediaType}, size_bytes=#{entry.sizeBytes}, updated_at=#{now}, updated_by=#{actor}
WHERE dataset_id=#{datasetId} AND storage_path=(SELECT source.storage_path FROM dataset_image source WHERE source.image_id=#{entry.entryId})

UPDATE dataset_file SET is_deleted=FALSE, original_filename=#{entry.originalFilename}, description=#{entry.description,jdbcType=VARCHAR},
  media_type=#{entry.mediaType}, size_bytes=#{entry.sizeBytes}, updated_at=#{now}, updated_by=#{actor}
WHERE dataset_id=#{datasetId} AND storage_path=(SELECT source.storage_path FROM dataset_file source WHERE source.file_id=#{entry.entryId})
